        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()
        Thread.sleep(forTimeInterval: 12)
        app.coordinate(withNormalizedOffset: CGVector(dx: 0.69, dy: 0.935)).tap()
        Thread.sleep(forTimeInterval: 3)
    }
